def nonlinear_limb_darkening(
    mu: Any, c0: Any = 0.0, c1: Any = 0.0, c2: Any = 0.0, c3: Any = 0.0
) -> object {
    return (
        1.0
        - (
            (c0 * (1.0 - (mu ** 0.5)))
            + (c1 * (1.0 - mu))
            + (c2 * (1.0 - (mu ** 1.5)))
            + (c3 * (1.0 - (mu ** 2)))
        )
    );
}

